await runTest('generated reports create an idempotent Inbox review queue', async () => {
  const previousRoot = process.env.RESEARCH_VAULT_ROOT;
  const tempRoot = mkdtempSync(join(tmpdir(), 'research-spine-flow-'));
  const inboxPath = join(tempRoot, '04_Human_Notes', 'Inbox.md');

  try {
    process.env.RESEARCH_VAULT_ROOT = tempRoot;
    mkdirSync(join(tempRoot, '04_Human_Notes'), { recursive: true });
    writeFileSync(inboxPath, '# Human Inbox\n\n## Open\n\n- [ ] Existing human task\n', 'utf-8');

    const result = await pull({
      documents: 'eod-monitoring,eod-briefing',
      'stale-ok': true,
    });

    assert.equal(result.documents.length, 2);

