function writeInboxReviewQueue(researchRoot, writtenEntries, readinessResults, flags) {
  if (flags['no-inbox'] || flags.noInbox) {
    console.log('--no-inbox: skipping report review Inbox write.');
    return null;
  }

  const reportEntries = writtenEntries.filter(entry => {
    const spec = DOCUMENTS[entry.docKey];
    return spec && ['monitoring_snapshot', 'briefing'].includes(spec.kind);
  });

  if (reportEntries.length === 0) return null;

  const inboxPath = join(researchRoot, '04_Human_Notes', 'Inbox.md');
  if (!existsSync(inboxPath)) {
    console.warn(`Warning: Inbox.md not found at ${inboxPath} - skipping report review Inbox write.`);
    return null;
  }

  const heading = `## Report Review Queue - ${today()}`;
  const taskLines = reportEntries.map(entry => {
    const spec = DOCUMENTS[entry.docKey];
    const cadence = normalizeReadinessCadence(spec.cadence);
    const readiness = readinessStatusForDocument(entry.docKey, readinessResults);
    const title = basename(entry.filePath, '.md');
    return `- [ ] [report-review/${cadence}] Review [[${title}]] - readiness: ${readiness}`;
  });

  const sectionBlock = [
    heading,
    '',
    taskLines.join('\n'),
    '',
  ].join('\n');

  let inboxRaw = readFileSync(inboxPath, 'utf-8');
  if (inboxRaw.charCodeAt(0) === 0xFEFF) inboxRaw = inboxRaw.slice(1);

  const escapedHeading = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const sectionRe = new RegExp(`${escapedHeading}[\\s\\S]*?(?=\\n## |$)`);
  const nextInbox = sectionRe.test(inboxRaw)
    ? inboxRaw.replace(sectionRe, sectionBlock.trimEnd())
    : `${inboxRaw.trimEnd()}\n\n${sectionBlock.trimEnd()}\n`;

  writeFileSync(inboxPath, nextInbox, 'utf-8');
  console.log(`Inbox: wrote ${reportEntries.length} report review task(s) to ${inboxPath}`);
  return inboxPath;
}

function readinessStatusForDocument(docKey, readinessResults) {
  const cadence = readinessCadenceForDocument(docKey);
  if (!cadence) return 'N/A';
  const result = arrayFrom(readinessResults).find(item => item.cadence === cadence);
  return result?.status || 'UNKNOWN';
}

